+  "pnpm",
+  [
+    "install",
+    "--frozen-lockfile",
+    "--ignore-scripts",
+    "--no-optimistic-repeat-install",
+    ...(brokenDependencies ? ["--force"] : []),
+  ],
+  source,
+);
+if (!existsSync(join(source, "node_modules/vitest/package.json")))
+  throw new Error("Source dependency restoration left dangling links");
